import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new RuntimeException();
                }
                res = res * 10 + c - '0';
                c = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int N = scanner.nextInt();
        if (N == -1) return;
        int M = scanner.nextInt();

        int[] T = new int[N];
        for (int i = 0; i < N; i++) {
            T[i] = scanner.nextInt();
        }

        int[] F = new int[M];
        for (int j = 0; j < M; j++) {
            F[j] = scanner.nextInt();
        }

        if (N <= M) {
            System.out.println(0);
            return;
        }

        // Busca binária pelo menor X tal que a quantidade de slots <= X seja >= N
        long low = 0;
        long high = 1_000_000_000L;
        long X = high;

        while (low <= high) {
            long mid = (low + high) >>> 1;
            long count = 0;
            for (int j = 0; j < M; j++) {
                count += (mid / F[j]) + 1;
                if (count >= N) break;
            }
            if (count >= N) {
                X = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        // Coletar todos os slots com valor < X
        long[] slots = new long[N];
        int count = 0;

        for (int j = 0; j < M; j++) {
            long maxP = (X - 1) / F[j];
            for (long p = 0; p <= maxP; p++) {
                slots[count++] = p * F[j];
            }
        }

        // Ordenar os slots estritamente menores que X
        Arrays.sort(slots, 0, count);

        // Preencher o restante dos N slots com o valor X
        while (count < N) {
            slots[count++] = X;
        }

        // Ordenar T em ordem decrescente (ou crescente e parear adequadamente)
        Arrays.sort(T);

        long totalWait = 0;
        for (int i = 0; i < N; i++) {
            // T[N - 1 - i] é o maior, pareado com slots[i] que é o menor
            totalWait += (long) T[N - 1 - i] * slots[i];
        }

        System.out.println(totalWait);
    }
}
